`)

	if !report.StartTime.IsZero() && !report.EndTime.IsZero() {
		sb.WriteString(fmt.Sprintf(`        <div class="period">%s to %s</div>
`,
			report.StartTime.Format("2006-01-02"),
			report.EndTime.Format("2006-01-02")))
	}

	sb.WriteString(`    </div>

    <div class="stats-grid">
        <div class="stat-card">
