	sb.WriteString(formatNumber(report.TotalTokens))
	sb.WriteString(`</div>
        </div>
        <div class="stat-card">
            <div class="stat-label">Est. Cost</div>
            <div class="stat-value">$`)
	sb.WriteString(fmt.Sprintf("%.2f", report.EstimatedCost))
	sb.WriteString(`</div>
        </div>
    </div>
`)

	// Agents section
	if len(report.AgentStats) > 0 {
		sb.WriteString(`    <div class="section">
        <h2>Agents</h2>
        <table>
            <thead>
                <tr>
                    <th>Agent</th>
                    <th>Sessions</th>
                    <th>Tokens</th>
                    <th>Hours</th>
                </tr>
            </thead>
            <tbody>
`)
		for _, stat := range report.AgentStats {
			agentName := string(stat.Agent)
			if agentName == "" {
				agentName = "unknown"
			}
			sb.WriteString(fmt.Sprintf(`                <tr>
                    <td>%s</td>
                    <td>%d</td>
                    <td>%s</td>
                    <td>%.1f</td>
                </tr>
`,
				agentName,
				stat.Sessions,
				formatNumber(stat.Tokens),
				stat.Hours))
		}
		sb.WriteString(`            </tbody>
        </table>
    </div>
`)
	}

	// Top tools section
	if len(report.TopTools) > 0 {
		sb.WriteString(`    <div class="section">
