	if len(report.TopTools) > 0 {
		sb.WriteString("TOP TOOLS\n")
		sb.WriteString("───────────────────────────────────────────────────────\n")
		for _, tool := range report.TopTools {
			sb.WriteString(fmt.Sprintf("  %-30s %s uses\n",
				tool.Name,
				formatNumber(tool.Count)))
		}
		sb.WriteString("\n")
	}

