	sb.WriteString("PEAK HOURS\n")
	sb.WriteString("───────────────────────────────────────────────────────\n")
	sb.WriteString(renderHeatmap(report.PeakHours))
	sb.WriteString("\n")

	// Recent sessions
	if len(report.RecentSessions) > 0 {
		sb.WriteString("RECENT SESSIONS\n")
		sb.WriteString("───────────────────────────────────────────────────────\n")
		for _, sess := range report.RecentSessions {
