                    <th>Tokens</th>
                </tr>
            </thead>
            <tbody>
`)
		for _, sess := range report.RecentSessions {
			desc := sess.Description
			if desc == "" {
				desc = sess.ID
			}
			if len(desc) > 50 {
				desc = desc[:47] + "..."
			}
			sb.WriteString(fmt.Sprintf(`                <tr>
                    <td>%s</td>
                    <td>%s</td>
                    <td>%s</td>
                    <td>%s</td>
                </tr>
`,
