				formatDuration(sess.Duration),
				desc,
				formatNumber(sess.Tokens)))
		}
		sb.WriteString(`            </tbody>
        </table>
    </div>
`)
	}

	sb.WriteString(`</body>
</html>`)

	return []byte(sb.String()), nil
}

