            width: 240px;
            padding: 32px 16px;
            background: #ffffff;
            border-right: 1px solid #d0d7de;
        }
        .sidebar nav {
            margin-top: 24px;
        }
        .nav-item {
            display: block;
            padding: 8px 12px;
            color: #1f2328;
            text-decoration: none;
            border-radius: 6px;
            margin-bottom: 4px;
            font-size: 14px;
