	sb.WriteString(greeting)
	sb.WriteString(`, developer</div>

        <!-- Stats Grid -->
        <div class="stats-grid">
            <div class="stat-card">
                <div class="stat-label">Sessions</div>
                <div class="stat-value">`)
	sb.WriteString(formatNumber(report.TotalSessions))
	sb.WriteString(`</div>
            </div>
