		}

		sb.WriteString(`
                    </tbody>
                </table>
            </div>
        </div>

        <div class="spacer"></div>`)
	}

	// Top Tools Table
	if len(report.TopTools) > 0 {
		sb.WriteString(`
        <div class="section">
            <div class="section-title">Top Tools</div>
